do $guard$
begin
  if (select count(*) from public.safety_spots p join dev10_batch b using(source_key)
      where p.active and not p.duplicate_candidate) <> 18
     or (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate) <> 47326
     then raise exception 'Post-insert count mismatch'; end if;
end;
